package cn.rainnotify.app.question

import cn.rainnotify.app.answer.*
import cn.rainnotify.app.auth.RainProtocol
import cn.rainnotify.app.ui.ImageSampling
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Rule
import org.junit.Test
import org.junit.rules.TemporaryFolder
import java.io.ByteArrayOutputStream
import java.util.UUID
import java.util.Base64

class ClassroomReviewTest {
    @get:Rule val temporary = TemporaryFolder()
    private fun record(at: Long, lesson: String = "10", scope: String = "account-a") = QuestionRecord(
        UUID.randomUUID().toString(), QuestionRef(lesson, "20", "30"), at,
        QuestionContent(1, "<p>题干</p>", listOf(QuestionOption("A", "A", "选项")), emptyList(), 1, emptyList()),
        "已保存", false, lessonName="课程 · 班级", accountScope=scope)

    @Test fun readsCourseNameAndKeepsOlderResponsesCompatible() {
        val lessons = RainProtocol.lessons(JSONObject("""{"code":0,"data":{"onLessonClassrooms":[
            {"lessonId":"10","classroomName":"一班","courseName":"世界史"},
            {"lessonId":"11","classroomName":"二班"}]}}"""))
        assertEquals("世界史 · 一班", lessons[0].displayName)
        assertEquals("二班", lessons[1].displayName)
    }
    @Test fun imageDownsamplingIsPositiveAndBounded() {
        assertEquals(1, ImageSampling.sampleSize(1280,720))
        assertEquals(2, ImageSampling.sampleSize(4096,2048))
        assertEquals(4, ImageSampling.sampleSize(8192,8192))
        assertThrows(IllegalArgumentException::class.java) { ImageSampling.sampleSize(0,10) }
    }
    @Test fun defaultStorageKeepsMoreThanTwentyQuestionsAndTheirResults() {
        val root = temporary.newFolder(); val files = QuestionFiles(root)
        val first = record(1); files.write(first); files.saveImage(first.id,0,byteArrayOf(1,2))
        files.saveAnswer(AnswerTask(UUID.randomUUID().toString(),first.id,true,AnswerPhase.SUBMITTED,"已确认",listOf("A"),model=DeepSeekModel.PRO))
        (2L..35L).forEach { files.write(record(it)) }
        val reopened=QuestionFiles(root)
        assertEquals(35,reopened.records().size)
        assertNotNull(reopened.image(first.id,0))
        assertEquals(listOf("A"),reopened.answers()[first.id]!!.answer)
        assertEquals(DeepSeekModel.PRO,reopened.answers()[first.id]!!.model)
        assertEquals("课程 · 班级",reopened.records().last().lessonName)
    }
    @Test fun groupsByLessonAcrossLoginSessionsAndMigratesOldMetadata() {
        val a=record(2); val b=record(1); val c=record(3,"11"); val d=record(4,scope="account-b")
        val groups=StudyClassrooms.group(listOf(a,b,c,d))
        assertEquals(2,groups.size)
        assertEquals(listOf(b.id,a.id,d.id),groups.single { it.key==a.classroomKey }.records.map { it.id })
        val json=a.json().also { it.remove("lesson_name");it.remove("account_scope");it.remove("recovered") }
        val old=QuestionRecord.fromJson(json)
        assertEquals("",old.lessonName); assertEquals(a.content!!.bodyHtml,old.content!!.bodyHtml)
    }
    @Test fun studyExportEmbedsOriginalImageAndHasNoPrivateIdsOrSourceLinks() {
        val files=QuestionFiles(temporary.newFolder()); val base=record(1)
        val q=base.changed(content=QuestionContent(1,"<script>alert(1)</script><p onclick='x'>题干<img src='https://secret.example/a?token=x'></p>",
            listOf(QuestionOption("A","internal-key","选项")),listOf(QuestionAsset("原图","https://secret.example/a?token=x")),1,emptyList()))
        files.write(q)
        val bytes=Base64.getDecoder().decode("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+a/jIAAAAASUVORK5CYII=")
        files.saveImage(q.id,0,bytes)
        files.saveAnswer(AnswerTask(UUID.randomUUID().toString(),q.id,true,AnswerPhase.SUBMITTED,"已确认",listOf("A")))
        val output=ByteArrayOutputStream();files.exportStudy(output,q.classroomKey)
        val html=output.toString("UTF-8")
        assertTrue(html.contains("data:image/png;base64,"+Base64.getEncoder().encodeToString(bytes)))
        assertTrue(html.contains("已提交（雨课堂已确认）"))
        assertTrue(html.contains("<details open>"))
        for (secret in listOf(q.id,"account-a","internal-key","secret.example","token=x","onclick=","<script>")) assertFalse(secret,html.contains(secret))
    }
    @Test fun exportsChoiceAndShortAnswerAsAReadableOfflineReviewDocument() {
        val files=QuestionFiles(temporary.newFolder())
        val at=java.time.Instant.parse("2026-10-28T06:00:00Z").toEpochMilli()
        val q=QuestionRecord(UUID.randomUUID().toString(),QuestionRef("demo-lesson","demo-slide","demo-q"),at,
            QuestionContent(1,"<p>下列哪座城市是意大利的首都？</p>",
                listOf(QuestionOption("A",null,"罗马"),QuestionOption("B",null,"伦敦")),
                listOf(QuestionAsset("题目原图","https://unused.example/image")),null,emptyList()),
            "已保存",false,lessonName="通识课程 · 复习示例")
        // Synthetic image fixture; no real classroom data or desktop Java dependency.
        val bytes=Base64.getDecoder().decode("")
        files.write(q);files.saveImage(q.id,0,bytes)
        files.saveAnswer(AnswerTask(UUID.randomUUID().toString(),q.id,true,AnswerPhase.SUBMITTED,"已确认",listOf("A")))
        val short=QuestionRecord(UUID.randomUUID().toString(),q.reference,at+60_000,
            QuestionContent(5,"简述史料相互印证的作用。",emptyList(),emptyList(),null,emptyList()),
            "已保存",false,lessonName=q.lessonName)
        files.write(short);files.saveAnswer(AnswerTask(UUID.randomUUID().toString(),short.id,true,AnswerPhase.SUBMITTED,"已确认",listOf("不同来源的史料相互对照，可以发现偏差，提高对历史事实判断的可靠性。")))
        val output=ByteArrayOutputStream();files.exportStudy(output,q.classroomKey)
        val html=output.toString("UTF-8")
        assertTrue(html.contains("共 2 题"));assertTrue(html.contains("主观"));assertTrue(html.contains("史料相互对照"))
        java.io.File("build/reports/review/study-notes.html").apply { parentFile!!.mkdirs();writeBytes(output.toByteArray()) }
    }

    @Test fun exportIncludesOnlySelectedClassroomAndLabelsMissingPictures() {
        val files=QuestionFiles(temporary.newFolder());val first=record(1);val other=record(2,"11").changed(content=QuestionContent(5,"OTHER-PRIVATE-QUESTION",emptyList(),emptyList(),null,emptyList()))
        files.write(first.changed(content=QuestionContent(5,"本课题目",emptyList(),listOf(QuestionAsset("附图","hidden-url")),null,emptyList())))
        files.write(other)
        val output=ByteArrayOutputStream();files.exportStudy(output,first.classroomKey)
        val html=output.toString("UTF-8")
        assertTrue(html.contains("原图尚未保存"));assertFalse(html.contains("OTHER-PRIVATE-QUESTION"))
        assertThrows(IllegalArgumentException::class.java) { files.exportStudy(ByteArrayOutputStream(),"absent") }
    }
}
